        if (frame._xd_zz_fx_timer) clearTimeout(frame._xd_zz_fx_timer);
        frame._xd_zz_fx_timer = setTimeout(() => {
            try { frame.classList.remove("xd-zz-v219-switchfx"); } catch (e) {}
        }, 560);
