        document.addEventListener("keydown", Z.v283StoryKeyHandler, true);
        document.body.appendChild(host);
        Z.v283StoryHost = host;
        try { host.focus({ preventScroll:true }); } catch (e) { try { host.focus(); } catch (e2) {} }
