            const name = get.name(card, player);
            if (name === "nanman" || name === "wanjian" || !get.tag(card, "damage")) return;
            const evt = _status.event;
            if (!evt || evt.name !== "chooseToUse" || evt.type !== "phase" || evt.player !== player) return;
