                    filterCard: () => true,
                    ai1(card) {
                      return lib.skill.xd_xuebian_backup.check(card);
                    },
                    check(card) {
                      if (ui.selected.cards.length >= min) return 0;
                      return 20 - get.value(card, player);
                    }
